import {
  type AuthoringArtifact,
  type FoldIssue,
  attach,
  requiredFieldsIssues,
  universalFoldsIssues,
} from './marketplace-tier.js';

// ─── Required-field sets (the source of the effective-required manifest) ─────

/** standardFloor — the upstream-base always-required fields (MCP spec + code.claude.com mcp). */
export const MCP_CONFIG_BASE_REQUIRED = ['name', 'command', 'args', 'transport', 'env'] as const;

/** The IS-overlay required delta (beyond the base floor). */
export const MCP_CONFIG_OVERLAY_REQUIRED = ['description', 'version', 'enabled'] as const;

/** Effective required = base ∪ overlay = the IS 8-field marketplace set (NON-NEGOTIABLE). */
export const MCP_CONFIG_REQUIRED_FIELDS = [
  ...MCP_CONFIG_BASE_REQUIRED,
  ...MCP_CONFIG_OVERLAY_REQUIRED,
] as const;

// ─── Constraint constants (mirror the JSON Schemas exactly) ──────────────────

/** MCP spec + code.claude.com mcp kebab-case name surface (upstream-base). */
export const MCP_NAME_PATTERN = /^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/;
/** MCP spec + code.claude.com mcp name length ceiling (upstream-base). */
export const MCP_NAME_MAX = 64;
/** MCP spec + code.claude.com mcp transport allowed values (upstream-base). */
export const MCP_TRANSPORT_VALUES = ['stdio', 'http', 'sse', 'ws'] as const;
/** Strict SemVer 2.0.0 (is-overlay — stricter than the legacy IS prefix match). */
export const SEMVER_PATTERN =
  /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$/;

function isStringArray(value: unknown): value is string[] {
  return Array.isArray(value) && value.every((item) => typeof item === 'string');
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

// ─── Layer 1: upstream base (authored by THEM) ───────────────────────────────

/**
 * The MCP-spec + code.claude.com mcp projection. Required presence of the
 * launch surface ([name, command, args, transport, env]) + type/constraint on
 * the upstream-owned fields (kebab-case name, non-empty command, array args,
 * transport enum {stdio,http,sse,ws}, object env). Length of `description` is
 * intentionally NOT capped here — the universal disclosureMarkers fold (1536)
 * is the operative cap (encoding a tighter cap would violate the
 * monotonic-additive invariant against the IS 1536 tier).
 */
export function upstreamBaseIssues(artifact: AuthoringArtifact): FoldIssue[] {
  const issues: FoldIssue[] = [...requiredFieldsIssues(artifact, MCP_CONFIG_BASE_REQUIRED)];

  if ('name' in artifact) {
    const name = artifact['name'];
    if (typeof name !== 'string') {
      issues.push({ message: 'name must be a string', path: ['name'] });
    } else {
      if (name.length > MCP_NAME_MAX) {
        issues.push({
          message: `name must be at most ${MCP_NAME_MAX} characters`,
          path: ['name'],
        });
      }
      if (!MCP_NAME_PATTERN.test(name)) {
        issues.push({
          message: 'name must be kebab-case (lowercase letters, digits, hyphens)',
          path: ['name'],
        });
      }
    }
  }

  if ('command' in artifact) {
    const command = artifact['command'];
    if (typeof command !== 'string') {
      issues.push({ message: 'command must be a string', path: ['command'] });
    } else if (command.length < 1) {
      issues.push({ message: 'command must not be empty', path: ['command'] });
    }
  }

  if ('args' in artifact && !isStringArray(artifact['args'])) {
    issues.push({ message: 'args must be an array of strings', path: ['args'] });
  }

  if ('transport' in artifact) {
    const transport = artifact['transport'];
    if (typeof transport !== 'string') {
      issues.push({ message: 'transport must be a string', path: ['transport'] });
    } else if (!(MCP_TRANSPORT_VALUES as readonly string[]).includes(transport)) {
      issues.push({
        message: `transport must be one of: ${MCP_TRANSPORT_VALUES.join(', ')}`,
        path: ['transport'],
      });
    }
  }

  if ('env' in artifact && !isPlainObject(artifact['env'])) {
    issues.push({ message: 'env must be an object', path: ['env'] });
  }

  if ('metadata' in artifact && !isPlainObject(artifact['metadata'])) {
    issues.push({ message: 'metadata must be an object', path: ['metadata'] });
  }

  return issues;
}

// ─── Layer 3: IS overlay (authored by US) ────────────────────────────────────

/**
 * The IS-only delta: three net-new IS-required tracking/operational fields
 * (description, version, enabled) + the SemVer narrowing on version. A field
 * whose type is already enforced by the base (the overlay only adds it to
 * required) is not re-typed here — its presence is the required check — to keep
 * messages single-sourced.
 */
export function isOverlayIssues(artifact: AuthoringArtifact): FoldIssue[] {
  const issues: FoldIssue[] = [...requiredFieldsIssues(artifact, MCP_CONFIG_OVERLAY_REQUIRED)];

  if ('description' in artifact && typeof artifact['description'] !== 'string') {
    issues.push({ message: 'description must be a string', path: ['description'] });
  }

  if ('version' in artifact) {
    const version = artifact['version'];
    if (typeof version !== 'string') {
      issues.push({ message: 'version must be a string', path: ['version'] });
    } else if (!SEMVER_PATTERN.test(version)) {
      issues.push({ message: 'version must be strict SemVer 2.0.0', path: ['version'] });
    }
  }

  if ('enabled' in artifact && typeof artifact['enabled'] !== 'boolean') {
    issues.push({ message: 'enabled must be a boolean', path: ['enabled'] });
  }

  return issues;
}

// ─── The composition (allOf of base + universal folds + overlay) ─────────────

/** Every issue from the three composed layers, in layer order. */
export function mcpConfigIssues(artifact: AuthoringArtifact): FoldIssue[] {
  return [
    ...upstreamBaseIssues(artifact),
    ...universalFoldsIssues(artifact),
    ...isOverlayIssues(artifact),
  ];
}

/** The mcp-config contract — pure allOf composition (base ∧ universalFolds ∧ overlay). */
export const McpConfigSchema = attach(mcpConfigIssues);

export type McpConfig = AuthoringArtifact;
